#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.hookshotDrowned_State)]
    public class HookshotDrowned_StateBehaviour : EnemyStateBehaviour
    {
        public HookshotDrowned_StateBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override int GetActiveState(Entity enemy)
        {
            if (HookshotUserBuff.IsHooking(enemy))
            {
                return VanillaEnemyStates.HOOKSHOT_DROWNED_HOOK;
            }
            return base.GetActiveState(enemy);
        }
    }
}
